56	func main() {
57		cfg, err := config.Load()
58		if err != nil {
59			log.Fatalf("config: %v", err)
60		}
61	
62		redisOpt, err := queue.RedisOpt(cfg.RedisURL)
63		if err != nil {
64			log.Fatalf("redis: %v", err)
65		}
66		client := asynq.NewClient(redisOpt)
67		defer client.Close()
68	
69		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
70		defer cancel()
71	
72		pool, err := pgxpool.New(ctx, cfg.DatabaseURL)
73		if err != nil {
74			log.Fatalf("pgxpool.New: %v", err)
75		}
76		defer pool.Close()
77		if err := pool.Ping(ctx); err != nil {
78			log.Fatalf("ping db: %v", err)
79		}
80	
81		h := &serviceHandler{
82			db:            dbadapter.New(pool),
83			q:             database.New(pool),
84			github:        ghadapter.New(cfg.GitHubToken),
85			token:         cfg.GitHubToken,
86			queue:         client,
87			webhookSecret: cfg.WebhookSecret,
88		}
89	
90		mux := http.NewServeMux()
91		mux.HandleFunc("/healthz", func(w http.ResponseWriter, _ *http.Request) {
92			w.WriteHeader(http.StatusOK)
93			fmt.Fprintln(w, `{"status":"ok"}`)
94		})
95		mux.HandleFunc("/internal/workspaces/import", h.importWorkspaceHandler)
96		mux.HandleFunc("/internal/workspaces/", h.internalWorkspaceHandler)
97		mux.HandleFunc("/webhook", h.webhookHandler)
98	
99		srv := &http.Server{
100			Addr:         fmt.Sprintf(":%d", cfg.Port),
101			Handler:      mux,
102			ReadTimeout:  120 * time.Second,
103			WriteTimeout: 120 * time.Second,
104			IdleTimeout:  60 * time.Second,
105		}
106	
107		done := make(chan os.Signal, 1)
108		signal.Notify(done, os.Interrupt, syscall.SIGTERM)
109	
110		go func() {
111			log.Printf("adapter-service listening on :%d", cfg.Port)
112			if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
113				log.Fatalf("listen: %v", err)
114			}
115		}()
116	
117		<-done
118		log.Println("adapter-service: shutting down")
119	
120		shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 10*time.Second)
121		defer shutdownCancel()
122	
123		if err := srv.Shutdown(shutdownCtx); err != nil {
124			log.Printf("shutdown: %v", err)
125		}
126	}
