128	func (h *serviceHandler) importWorkspaceHandler(w http.ResponseWriter, r *http.Request) {
129		if r.Method != http.MethodPost {
130			w.Header().Set("Allow", http.MethodPost)
131			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
132			return
133		}
134	
135		defer r.Body.Close()
136		var req importWorkspaceRequest
137		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
138			writeSourceError(w, domain.NewValidationError(domain.ErrValidationMissingInput, "invalid JSON body: "+err.Error()))
139			return
140		}
141		if strings.TrimSpace(req.RepoURL) == "" {
142			writeSourceError(w, domain.NewValidationError(domain.ErrValidationMissingInput, "repo_url is required"))
143			return
144		}
145		if req.DefaultBranch == "" {
146			req.DefaultBranch = "main"
147		}
148	
149		workspaceID := uuid.NewString()
150		name := strings.TrimSpace(req.Name)
151		if name == "" {
152			owner, repo, err := parseGitHubRepo(req.RepoURL)
153			if err != nil {
154				writeAnyError(w, err)
155				return
156			}
157			name = owner + "/" + repo
158		}
159		slug := slugify(name)
160		if slug == "" {
161			slug = workspaceID
162		}
163	
164		workspaceID, err := h.createImportPlaceholder(r.Context(), workspaceID, name, slug, req.RepoURL, req.DefaultBranch)
165		if err != nil {
166			writeAnyError(w, err)
167			return
168		}
169		run, err := h.insertRunningRun(r.Context(), workspaceID, "api_import", "full", req.DefaultBranch)
170		if err != nil {
171			writeAnyError(w, err)
172			return
173		}
174		syncRunID := uuidString(run.ID)
175	
176		payload := queue.WorkspaceSyncPayload{
177			WorkspaceID:   workspaceID,
178			RepoURL:       req.RepoURL,
179			DefaultBranch: req.DefaultBranch,
180			Trigger:       "api_import",
181			Mode:          "full",
182			Name:          name,
183			SyncRunID:     syncRunID,
184		}
185		task, err := queue.NewWorkspaceSyncTask(payload)
186		if err != nil {
187			writeAnyError(w, err)
188			return
189		}
190		info, err := h.queue.Enqueue(task)
191		if err != nil {
192			if failErr := h.markRunFailed(r.Context(), run.ID, "ENQUEUE_FAILED", err.Error()); failErr != nil {
193				log.Printf("mark import enqueue failed run failed workspace_id=%s run_id=%s: %v", workspaceID, syncRunID, failErr)
194			}
195			writeAnyError(w, fmt.Errorf("enqueue task: %w", err))
196			return
197		}
198	
199		writeJSON(w, http.StatusAccepted, map[string]string{
200			"workspace_id":   workspaceID,
201			"name":           name,
202			"slug":           slug,
203			"repo_url":       req.RepoURL,
204			"default_branch": req.DefaultBranch,
205			"sync_run_id":    syncRunID,
206			"task_id":        info.ID,
207			"queue":          info.Queue,
208			"type":           info.Type,
209		})
210	}
