212	func (h *serviceHandler) internalWorkspaceHandler(w http.ResponseWriter, r *http.Request) {
213		if r.Method != http.MethodPost {
214			w.Header().Set("Allow", http.MethodPost)
215			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
216			return
217		}
218	
219		workspaceID, ok := workspaceIDFromSyncPath(r.URL.Path)
220		if !ok {
221			http.NotFound(w, r)
222			return
223		}
224	
225		uid, err := pgUUID(workspaceID)
226		if err != nil {
227			writeAnyError(w, err)
228			return
229		}
230		src, err := h.q.GetGitHubSource(r.Context(), uid)
231		if err != nil {
232			if errors.Is(err, pgx.ErrNoRows) {
233				writeSourceError(w, domain.NewDatabaseError(domain.ErrDatabaseNotFound, "github source not found for workspace"))
234				return
235			}
236			writeAnyError(w, err)
237			return
238		}
239	
240		defaultBranch := "main"
241		if src.DefaultBranch != nil && *src.DefaultBranch != "" {
242			defaultBranch = *src.DefaultBranch
243		}
244		payload := queue.WorkspaceSyncPayload{
245			WorkspaceID:   workspaceID,
246			RepoURL:       src.RepoURL,
247			DefaultBranch: defaultBranch,
248			Trigger:       "api_sync",
249			Mode:          "full",
250		}
251		task, err := queue.NewWorkspaceSyncTask(payload)
252		if err != nil {
253			writeAnyError(w, err)
254			return
255		}
256		info, err := h.queue.Enqueue(task)
257		if err != nil {
258			writeAnyError(w, fmt.Errorf("enqueue task: %w", err))
259			return
260		}
261	
262		writeJSON(w, http.StatusAccepted, map[string]string{
263			"task_id": info.ID,
264			"queue":   info.Queue,
265			"type":    info.Type,
266		})
267	}
