269	// webhookHandler processes GitHub push event webhooks.
270	// It verifies the HMAC signature, parses the push payload, and routes based on branch:
271	//   - base branch → enqueue targeted workspace:sync for each touched feature
272	//   - feature branch → enqueue targeted workspace:sync for that feature
273	//   - task branch → enqueue task:sync with dedup
274	//   - other → 200 OK, ignored
275	func (h *serviceHandler) webhookHandler(w http.ResponseWriter, r *http.Request) {
276		if r.Method != http.MethodPost {
277			w.Header().Set("Allow", http.MethodPost)
278			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
279			return
280		}
281	
282		body, err := webhook.ReadAndVerify(r, h.webhookSecret)
283		if err != nil {
284			http.Error(w, "signature verification failed: "+err.Error(), http.StatusUnauthorized)
285			return
286		}
287	
288		// Only handle push events; ignore other event types gracefully.
289		eventType := r.Header.Get("X-GitHub-Event")
290		if eventType != "push" {
291			writeJSON(w, http.StatusOK, map[string]string{"status": "ignored", "event": eventType})
292			return
293		}
294	
295		ev, err := webhook.ParsePushEvent(body)
296		if err != nil {
297			http.Error(w, "invalid push event payload", http.StatusBadRequest)
298			return
299		}
300	
301		branch := webhook.BranchFromRef(ev.Ref)
302	
303		// Look up the workspace by repo URL to find workspaceID, defaultBranch, and branchPattern.
304		repoURL := ev.Repository.CloneURL
305		if repoURL == "" {
306			repoURL = ev.Repository.HTMLURL
307		}
308		wsInfo, dbErr := h.findWorkspaceByRepoURL(r.Context(), repoURL)
309		if dbErr != nil {
310			// Unknown repo — not an error from our side, just ignore.
311			log.Printf("webhook: repo not registered: %s", repoURL)
312			writeJSON(w, http.StatusOK, map[string]string{"status": "ignored", "reason": "repo not registered"})
313			return
314		}
315	
316		info := webhook.ClassifyBranch(branch, wsInfo.defaultBranch)
317		switch info.Kind {
318		case webhook.BranchIgnored:
319			writeJSON(w, http.StatusOK, map[string]string{"status": "ignored", "branch": branch})
320			return
321	
322		case webhook.BranchBase:
323			featureIDs := webhook.TouchedFeatureIDs(ev)
324			for _, fid := range featureIDs {
325				go h.enqueueTargetedSync(wsInfo, fid, branch)
326			}
327			writeJSON(w, http.StatusOK, map[string]string{
328				"status":           "queued",
329				"branch_kind":      "base",
330				"features_touched": fmt.Sprintf("%d", len(featureIDs)),
331			})
332	
333		case webhook.BranchFeature:
334			go h.enqueueTargetedSync(wsInfo, info.FeatureID, branch)
335			writeJSON(w, http.StatusOK, map[string]string{
336				"status":     "queued",
337				"branch_kind": "feature",
338				"feature_id": info.FeatureID,
339			})
340	
341		case webhook.BranchTask:
342			if err := h.enqueueTaskSync(wsInfo.workspaceID, info.FeatureID, info.TaskID); err != nil {
343				log.Printf("webhook: enqueue task sync failed workspace=%s feature=%s task=%s: %v",
344					wsInfo.workspaceID, info.FeatureID, info.TaskID, err)
345			}
346			writeJSON(w, http.StatusOK, map[string]string{
347				"status":     "queued",
348				"branch_kind": "task",
349				"feature_id": info.FeatureID,
350				"task_id":    info.TaskID,
351			})
352		}
353	}
354	
355	// workspaceWebhookInfo holds the minimal workspace data needed by webhook routing.
356	type workspaceWebhookInfo struct {
357		workspaceID   string
358		repoURL       string
359		defaultBranch string
360	}
361	
362	// findWorkspaceByRepoURL queries the DB for a workspace matching the given repo URL.
363	func (h *serviceHandler) findWorkspaceByRepoURL(ctx context.Context, repoURL string) (*workspaceWebhookInfo, error) {
364		owner, repo, err := parseGitHubRepo(repoURL)
365		if err != nil {
366			return nil, err
367		}
368		src, dbError := h.q.GetGitHubSourceByRepo(ctx, database.GetGitHubSourceByRepoParams{
369			RepoOwner: owner,
370			RepoName:  repo,
371		})
372		if dbError != nil {
373			return nil, dbError
374		}
375		defaultBranch := "main"
376		if src.DefaultBranch != nil && *src.DefaultBranch != "" {
377			defaultBranch = *src.DefaultBranch
378		}
379		return &workspaceWebhookInfo{
380			workspaceID:   uuidString(src.WorkspaceID),
381			repoURL:       src.RepoURL,
382			defaultBranch: defaultBranch,
383		}, nil
384	}
385	
386	// enqueueTargetedSync enqueues a workspace:sync task with mode=targeted for a single feature.
387	// It runs in a goroutine so the webhook handler returns immediately.
388	func (h *serviceHandler) enqueueTargetedSync(ws *workspaceWebhookInfo, featureID, branch string) {
389		payload := queue.WorkspaceSyncPayload{
390			WorkspaceID:   ws.workspaceID,
391			RepoURL:       ws.repoURL,
392			DefaultBranch: ws.defaultBranch,
393			Ref:           branch,
394			Trigger:       "webhook_feature",
395			Mode:          "targeted",
396			FeatureID:     featureID,
397		}
398		task, err := queue.NewWorkspaceSyncTask(payload)
399		if err != nil {
400			log.Printf("enqueueTargetedSync: build task error: %v", err)
401			return
402		}
403		if _, err := h.queue.Enqueue(task); err != nil {
404			log.Printf("enqueueTargetedSync: enqueue error workspace=%s feature=%s: %v",
405				ws.workspaceID, featureID, err)
406		}
407	}
408	
409	// enqueueTaskSync enqueues a task:sync job with deduplication.
410	func (h *serviceHandler) enqueueTaskSync(workspaceID, featureID, taskID string) error {
411		payload := queue.TaskSyncPayload{
412			WorkspaceID: workspaceID,
413			FeatureID:   featureID,
414			TaskID:      taskID,
415		}
416		task, err := queue.NewTaskSyncTask(payload)
417		if err != nil {
418			return fmt.Errorf("build task:sync task: %w", err)
419		}
420		info, err := h.queue.Enqueue(task)
421		if err != nil {
422			// ErrTaskIDConflict means duplicate — already queued, this is expected with Unique(24h).
423			if isDedupeError(err) {
424				log.Printf("task:sync already queued (dedup) workspace=%s feature=%s task=%s", workspaceID, featureID, taskID)
425				return nil
426			}
427			return fmt.Errorf("enqueue task:sync: %w", err)
428		}
429		log.Printf("task:sync enqueued id=%s workspace=%s feature=%s task=%s", info.ID, workspaceID, featureID, taskID)
430		return nil
431	}
432	
433	// isDedupeError returns true when the asynq error indicates a duplicate task (Unique constraint).
434	func isDedupeError(err error) bool {
435		return err != nil && strings.Contains(err.Error(), "task already exists")
436	}
