438	func (h *serviceHandler) createImportPlaceholder(ctx context.Context, workspaceID, name, slug, repoURL, defaultBranch string) (string, error) {
439		uid, err := pgUUID(workspaceID)
440		if err != nil {
441			return "", err
442		}
443		ws, err := h.q.UpsertWorkspace(ctx, database.UpsertWorkspaceParams{
444			ID:               uid,
445			Slug:             slug,
446			Name:             name,
447			ManagementRepoID: "management-repo",
448		})
449		if err != nil {
450			return "", fmt.Errorf("upsert import placeholder workspace: %w", err)
451		}
452		actualWorkspaceID := uuidString(ws.ID)
453		if err := h.upsertGitHubSource(ctx, actualWorkspaceID, repoURL, defaultBranch); err != nil {
454			return "", err
455		}
456		return actualWorkspaceID, nil
457	}
458	
459	func (h *serviceHandler) upsertGitHubSource(ctx context.Context, workspaceID, repoURL, defaultBranch string) error {
460		uid, err := pgUUID(workspaceID)
461		if err != nil {
462			return err
463		}
464		owner, repo, err := parseGitHubRepo(repoURL)
465		if err != nil {
466			return err
467		}
468		_, err = h.q.UpsertGitHubSource(ctx, database.UpsertGitHubSourceParams{
469			WorkspaceID:   uid,
470			RepoURL:       repoURL,
471			RepoOwner:     owner,
472			RepoName:      repo,
473			DefaultBranch: &defaultBranch,
474		})
475		if err != nil {
476			return fmt.Errorf("upsert github source: %w", err)
477		}
478		return nil
479	}
480	
481	func (h *serviceHandler) insertRunningRun(ctx context.Context, workspaceID, trigger, mode, branch string) (database.WorkspaceSyncRun, error) {
482		uid, err := pgUUID(workspaceID)
483		if err != nil {
484			return database.WorkspaceSyncRun{}, err
485		}
486		branchPtr := branch
487		row, err := h.q.InsertSyncRun(ctx, database.InsertSyncRunParams{
488			WorkspaceID:  uid,
489			Trigger:      trigger,
490			Branch:       &branchPtr,
491			Mode:         mode,
492			Status:       "running",
493			ChangedPaths: []byte("[]"),
494		})
495		if err != nil {
496			return database.WorkspaceSyncRun{}, fmt.Errorf("insert sync run: %w", err)
497		}
498		return row, nil
499	}
500	
501	func (h *serviceHandler) markRunFailed(ctx context.Context, runID pgtype.UUID, code, message string) error {
502		_, err := h.q.UpdateSyncRunFailed(ctx, database.UpdateSyncRunFailedParams{
503			ID:           runID,
504			ErrorCode:    &code,
505			ErrorMessage: &message,
506		})
507		if err != nil {
508			return fmt.Errorf("update sync run failed: %w", err)
509		}
510		return nil
511	}
512	
513	func uuidString(uid pgtype.UUID) string {
514		return uuid.UUID(uid.Bytes).String()
515	}
516	
517	func slugify(name string) string {
518		lower := strings.ToLower(name)
519		re := regexp.MustCompile(`[^a-z0-9]+`)
520		slug := re.ReplaceAllString(lower, "-")
521		return strings.Trim(slug, "-")
522	}
523	
524	func workspaceIDFromSyncPath(path string) (string, bool) {
525		const prefix = "/internal/workspaces/"
526		const suffix = "/sync"
527		if !strings.HasPrefix(path, prefix) || !strings.HasSuffix(path, suffix) {
528			return "", false
529		}
530		workspaceID := strings.TrimSuffix(strings.TrimPrefix(path, prefix), suffix)
531		workspaceID = strings.Trim(workspaceID, "/")
532		return workspaceID, workspaceID != ""
533	}
534	
535	func pgUUID(raw string) (pgtype.UUID, error) {
536		var uid pgtype.UUID
537		if err := uid.Scan(raw); err != nil {
538			return pgtype.UUID{}, domain.NewValidationError(domain.ErrValidationMissingInput, "invalid workspace_id: "+raw)
539		}
540		return uid, nil
541	}
542	
543	func parseGitHubRepo(raw string) (string, string, error) {
544		u, err := url.Parse(raw)
545		if err != nil || u.Host == "" {
546			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "invalid GitHub repo URL: "+raw)
547		}
548		if !strings.EqualFold(u.Host, "github.com") {
549			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "unsupported GitHub host: "+u.Host)
550		}
551		parts := strings.Split(strings.Trim(u.Path, "/"), "/")
552		if len(parts) < 2 || parts[0] == "" || parts[1] == "" {
553			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "invalid GitHub repo URL path: "+raw)
554		}
555		return parts[0], strings.TrimSuffix(parts[1], ".git"), nil
556	}
557	
558	func writeAnyError(w http.ResponseWriter, err error) {
559		var se domain.SourceError
560		if errors.As(err, &se) {
561			writeSourceError(w, se)
562			return
563		}
564		writeSourceError(w, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error()))
565	}
566	
567	func writeSourceError(w http.ResponseWriter, se domain.SourceError) {
568		status := http.StatusInternalServerError
569		switch se.Source {
570		case domain.ErrorSourceValidation:
571			status = http.StatusBadRequest
572		case domain.ErrorSourceGitHub:
573			switch se.Code {
574			case domain.ErrGitHubNotFound:
575				status = http.StatusNotFound
576			case domain.ErrGitHubUnauthorized:
577				status = http.StatusUnauthorized
578			case domain.ErrGitHubRateLimit:
579				status = http.StatusTooManyRequests
580			default:
581				status = http.StatusBadGateway
582			}
583		case domain.ErrorSourceDatabase:
584			if se.Code == domain.ErrDatabaseNotFound {
585				status = http.StatusNotFound
586			}
587		}
588		writeJSON(w, status, domain.FromSourceError(se, nil))
589	}
590	
591	func writeJSON(w http.ResponseWriter, status int, value interface{}) {
592		w.Header().Set("Content-Type", "application/json")
593		w.WriteHeader(status)
594		_ = json.NewEncoder(w).Encode(value)
595	}
