1	// Package webhook implements GitHub webhook signature verification, push event
2	// parsing, and branch routing for adapter-service.
3	package webhook
4	
5	import (
6		"crypto/hmac"
7		"crypto/sha256"
8		"encoding/hex"
9		"encoding/json"
10		"fmt"
11		"io"
12		"net/http"
13		"regexp"
14		"strings"
15	)
16	
17	// PushEvent is the subset of a GitHub push event payload that adapter-service needs.
18	type PushEvent struct {
19		Ref        string   `json:"ref"`
20		Repository Repository `json:"repository"`
21		Commits    []Commit   `json:"commits"`
22	}
23	
24	// Repository holds repository identity from the push payload.
25	type Repository struct {
26		FullName string `json:"full_name"`
27		HTMLURL  string `json:"html_url"`
28		CloneURL string `json:"clone_url"`
29	}
30	
31	// Commit holds the changed file lists from a single push commit.
32	type Commit struct {
33		Added    []string `json:"added"`
34		Modified []string `json:"modified"`
35		Removed  []string `json:"removed"`
36	}
37	
38	// BranchKind classifies the branch from a push event.
39	type BranchKind int
40	
41	const (
42		BranchIgnored     BranchKind = iota
43		BranchBase                   // base branch (e.g. "main")
44		BranchFeature                // feature/<feature-id>
45		BranchTask                   // feature/<feature-id>-T<n>
46	)
47	
48	// BranchInfo contains the parsed branch information.
49	type BranchInfo struct {
50		Kind      BranchKind
51		Branch    string
52		FeatureID string
53		TaskID    string
54	}
55	
56	// featureBranchRe matches "feature/<feature-id>" (no task suffix).
57	var featureBranchRe = regexp.MustCompile(`^feature/([^/]+)$`)
58	
59	// taskBranchRe matches "feature/<feature-id>-T<n>".
60	var taskBranchRe = regexp.MustCompile(`^feature/(.+)-(T\d+)$`)
61	
62	// featurePathRe matches docs/features/<feature-id>/ path prefixes.
63	var featurePathRe = regexp.MustCompile(`^docs/features/([^/]+)/`)
64	
65	// VerifySignature checks the X-Hub-Signature-256 header against the request body.
66	// Returns an error if the signature is missing or invalid.
67	func VerifySignature(secret string, header string, body []byte) error {
68		if secret == "" {
69			return nil
70		}
71		const prefix = "sha256="
72		if !strings.HasPrefix(header, prefix) {
73			return fmt.Errorf("missing or malformed X-Hub-Signature-256 header")
74		}
75		gotHex := strings.TrimPrefix(header, prefix)
76		mac := hmac.New(sha256.New, []byte(secret))
77		mac.Write(body)
78		wantHex := hex.EncodeToString(mac.Sum(nil))
79		if !hmac.Equal([]byte(gotHex), []byte(wantHex)) {
80			return fmt.Errorf("webhook signature mismatch")
81		}
82		return nil
83	}
84	
85	// ReadAndVerify reads the request body and verifies the GitHub HMAC signature.
86	// Returns the raw body bytes on success. The caller must not call r.Body.Read again.
87	func ReadAndVerify(r *http.Request, secret string) ([]byte, error) {
88		body, err := io.ReadAll(r.Body)
89		if err != nil {
90			return nil, fmt.Errorf("read webhook body: %w", err)
91		}
92		sig := r.Header.Get("X-Hub-Signature-256")
93		if err := VerifySignature(secret, sig, body); err != nil {
94			return nil, err
95		}
96		return body, nil
97	}
98	
99	// ParsePushEvent parses raw push event JSON into a PushEvent.
100	func ParsePushEvent(data []byte) (*PushEvent, error) {
101		var ev PushEvent
102		if err := json.Unmarshal(data, &ev); err != nil {
103			return nil, fmt.Errorf("parse push event: %w", err)
104		}
105		return &ev, nil
106	}
107	
108	// BranchFromRef strips the "refs/heads/" prefix from a git ref.
109	func BranchFromRef(ref string) string {
110		return strings.TrimPrefix(ref, "refs/heads/")
111	}
112	
113	// ClassifyBranch returns the BranchKind and parsed identifiers for the given branch name.
114	func ClassifyBranch(branch, baseBranch string) BranchInfo {
115		if branch == "" {
116			return BranchInfo{Kind: BranchIgnored}
117		}
118		if branch == baseBranch {
119			return BranchInfo{Kind: BranchBase, Branch: branch}
120		}
121		if m := taskBranchRe.FindStringSubmatch(branch); m != nil {
122			return BranchInfo{Kind: BranchTask, Branch: branch, FeatureID: m[1], TaskID: m[2]}
123		}
124		if m := featureBranchRe.FindStringSubmatch(branch); m != nil {
125			return BranchInfo{Kind: BranchFeature, Branch: branch, FeatureID: m[1]}
126		}
127		return BranchInfo{Kind: BranchIgnored, Branch: branch}
128	}
129	
130	// TouchedFeatureIDs extracts unique feature IDs from docs/features/<feature-id>/ paths
131	// across all commits in the push event.
132	func TouchedFeatureIDs(ev *PushEvent) []string {
133		seen := make(map[string]struct{})
134		var ids []string
135		for _, c := range ev.Commits {
136			for _, paths := range [][]string{c.Added, c.Modified, c.Removed} {
137				for _, p := range paths {
138					m := featurePathRe.FindStringSubmatch(p)
139					if m == nil {
140						continue
141					}
142					fid := m[1]
143					if _, dup := seen[fid]; !dup {
144						seen[fid] = struct{}{}
145						ids = append(ids, fid)
146					}
147				}
148			}
149		}
150		return ids
